"""Offline client handoff guide; original Logo Parcel styling."""
import base64,html,json,re
from collections import OrderedDict
from pathlib import Path
from urllib.parse import quote

def colour_section(colours, brand_files):
    esc=html.escape
    if not colours: return ''
    chips=[]
    for i,c in enumerate(colours):
        if not re.fullmatch(r"#[0-9a-fA-F]{6}",c.get("hex","")): continue
        rows=[('HEX',c['hex'].upper()),('RGB',' '.join(map(str,c['rgb']))),('CMYK',' '.join(map(str,c['cmyk'])))]
        if c.get('pantone'): rows.append(('PANTONE',c['pantone']))
        values=''.join('<div class="value"><span class="mono">'+k+'</span><button class="copy" data-copy="'+esc(v,quote=True)+'" title="Copy">'+esc(v)+'</button></div>' for k,v in rows)
        chips.append('<article class="swatch"><div class="chip" style="background:'+esc(c['hex'],quote=True)+'"></div><div class="swatch-body"><h3>'+esc(c.get('name') or 'Colour '+str(i+1))+'</h3>'+values+'<p class="used">'+esc(', '.join(c.get('items',[])))+'</p></div></article>')
    links=''
    if brand_files:
        links='<p class="downloads">'+''.join('<a class="file" download href="Brand-Colours/'+quote(brand_files+'-colours.'+ext)+'">'+label+'<span aria-hidden="true">↗</span></a>' for ext,label in (('ase','ASE · Adobe swatches'),('css','CSS variables'),('json','JSON')))+'</p>'
    return '<section class="section" id="colours"><p class="eyebrow"><span class="number">02</span> Brand colours</p><h2>Colour values</h2><p class="lede">Detected artwork colours: use RGB or HEX on screens. CMYK values use the selected export profile; confirm them with your printer. Pantone references are supplied by your designer, not calculated. Click a value to copy it.</p><div class="swatches">'+''.join(chips)+'</div>'+links+'</section>'

def usage_section(usage, hero, dark=False):
    esc=html.escape
    if not usage: return ''
    img=('<img alt="" src="data:image/png;base64,'+base64.b64encode(hero).decode('ascii')+'">') if hero and len(hero)<=3_000_000 else '<span class="no-preview">Logo</span>'
    sizes=''
    if usage.get('minDigital'): sizes+='<div class="rule-card"><strong>'+str(usage['minDigital'])+' px</strong><span class="mono">Minimum width on screen</span></div>'
    if usage.get('minPrint'): sizes+='<div class="rule-card"><strong>'+str(usage['minPrint'])+' mm</strong><span class="mono">Minimum width in print</span></div>'
    donts=[('stretch','Don’t stretch or squash it'),('rotate','Don’t rotate it'),('recolour','Don’t change its colours'),('shadow','Don’t add shadows or effects'),('busy','Don’t place it on busy images'),('outline','Don’t outline or crop it')]
    dont_html=''.join('<figure class="dont"><div class="dont-art '+k+'">'+img+'</div><figcaption><span class="cross" aria-hidden="true">✕</span>'+esc(t)+'</figcaption></figure>' for k,t in donts)
    pad=max(float(usage.get('padding',10)),4)
    notes='<p class="custom-notes">'+esc(usage['notes'])+'</p>' if usage.get('notes') else ''
    img='<div style="display:contents">'+img+'</div>' if not dark else img
    return ('<section class="section" id="usage"'+(' style="--logo-bg:#202022"' if dark else '')+'><p class="eyebrow"><span class="number">03</span> Using the logo</p><h2>Keep it clear and consistent</h2>'
      '<div class="usage-grid"><div class="clearspace"><div class="space" style="padding:'+f'{pad*1.6:.0f}'+'px">'+img+'</div><p><strong>Clear space.</strong> The export adds '+esc(str(usage.get('padding',10)))+'% of the logo’s longest side as padding on every side. This is export spacing, not a measured brand rule. Follow any separate brand guidelines. The diagram is illustrative.</p></div>'
      '<div class="rules">'+sizes+'<div class="rule-card do"><span class="tick" aria-hidden="true">✓</span><span>Use the supplied files as they are, on backgrounds with strong contrast. Use an approved white or dark-background version on dark colours.</span></div></div></div>'
      +notes+'<div class="donts">'+dont_html+'</div></section>')

def guide(brand, files, warnings, notes, previews=None, website='', colours=None, usage=None, hero=None, brand_files='', pdf_sheet=True, hero_dark=False):
    esc=html.escape
    previews=previews or {}
    groups=OrderedDict()
    for item in files:
        groups.setdefault((item.get('role',Path(item['path']).parts[0]),item.get('group') or item['variant'],item['mode']),[]).append(item)
    cards=[]
    for index,((role,variant,mode),items) in enumerate(groups.items(),1):
        candidates=[Path(previews[i['id']]) for i in items if previews.get(i['id']) and Path(previews[i['id']]).is_file()]
        visual='<div class="no-preview">'+esc(role)+'</div>'
        if candidates:
            # Web and social sets are previewed from their largest image; favicons are tiny.
            thumb=(max if items[0].get('group') else min)(candidates,key=lambda p:p.stat().st_size)
            if thumb.stat().st_size<=3_000_000:
                visual='<img alt="'+esc(role+' — '+variant.replace('-',' '),quote=True)+'" loading="lazy" src="data:image/png;base64,'+base64.b64encode(thumb.read_bytes()).decode('ascii')+'">'
        else:
            raster=next((i for i in items if i['format'] in ('png','svg','jpg')),None)
            if raster: visual='<img alt="'+esc(role,quote=True)+'" loading="lazy" src="'+quote(raster['path'],safe='/')+'">'
        links=[]
        for item in items:
            label=item.get('label') or item['format'].upper()+(' · '+str(item['size'])+'px' if item.get('size') else '')
            links.append('<a class="file" download href="'+quote(item['path'],safe='/')+'" title="'+esc(Path(item['path']).name,quote=True)+'">'+esc(label)+'<span aria-hidden="true">↗</span></a>')
        kind='WEB & SOCIAL' if items[0].get('group') else 'DIGITAL / RGB' if mode=='rgb' else 'PRINT / CMYK'
        cards.append('<article class="card" data-mode="'+esc(mode,quote=True)+'" data-search="'+esc((role+' '+variant).lower(),quote=True)+'"><div class="card-top"><span class="number">'+f'{index:02d}'+'</span><span class="mono">'+kind+'</span></div><div class="preview '+('dark' if variant in ('white','dark-background') else '')+'">'+visual+'</div><div class="card-content"><h3>'+esc(role)+'</h3><p class="variant">'+esc(variant.replace('-',' ').capitalize() if not items[0].get('group') else variant)+'</p><div class="files">'+''.join(links)+'</div></div></article>')
    credits='<a href="'+esc(website,quote=True)+'" target="_blank" rel="noopener noreferrer">Stellio Creative Labs ↗</a>' if website else 'Stellio Creative Labs'
    notes_html=''.join('<li>'+esc(n)+'</li>' for n in notes)
    warning_html='<aside class="warning"><h2>Before you use these files</h2><ul>'+''.join('<li>'+esc(w)+'</li>' for w in warnings)+'</ul></aside>' if warnings else ''
    sheet='<a href="'+quote(brand_files+'-Brand-Sheet.pdf')+'">Brand sheet (PDF) ↗</a>' if brand_files and pdf_sheet else ''
    nav=''.join(f'<a href="#{k}">{v}</a>' for k,v,on in (('files','Logo files',True),('colours','Colours',bool(colours)),('usage','Usage',bool(usage))) if on)
    values={'TITLE':esc(brand),'COUNT':str(len(files)),'LAYOUTS':str(len({i.get('role',str(i['layout'])) for i in files})),'CARDS':''.join(cards),'NOTES':notes_html,'WARNINGS':warning_html,'CREDITS':credits,'COLOURS':colour_section(colours,brand_files),'USAGE':usage_section(usage,hero,hero_dark),'SHEET':sheet,'NAV':nav}
    return re.sub(r'__(TITLE|COUNT|LAYOUTS|CARDS|NOTES|WARNINGS|CREDITS|COLOURS|USAGE|SHEET|NAV)__',lambda m:values[m[1]],TEMPLATE)

